export function getScale(num: number): string {
    if (num >= 1 && num <= 72) {
        const val = num - 1;
        const ma = ['M₁', 'M₂'][Math.floor(val / 36)];
        const by6 = val % 6;
        const by6chakra_ga = Math.floor(val / 6) % 6;
        
        const ni = ['N₁', 'N₂', 'N₃', 'N₂', 'N₃', 'N₃'][by6];
        const da = ['D₁', 'D₁', 'D₁', 'D₂', 'D₂', 'D₃'][by6];
        const ga = ['G₁', 'G₂', 'G₃', 'G₂', 'G₃', 'G₃'][by6chakra_ga];
        const ri = ['R₁', 'R₁', 'R₁', 'R₂', 'R₂', 'R₃'][by6chakra_ga];
        
        return `S ${ri} ${ga} ${ma} P ${da} ${ni}`;
    } else {
        throw new Error(`Invalid raga number: ${num}`);
    }
}
